<?php $title='Reservas'; require __DIR__.'/_top.php'; ?><div class="page-heading"><div><p class="eyebrow">Gerenciamento</p><h1>Reservas</h1></div></div><form class="filter-bar" method="get" action="<?= e(base_url('admin/reservas')) ?>"><input type="search" name="q" placeholder="Nome, codigo, e-mail ou telefone" value="<?= e($filters['q']??'') ?>"><select name="status"><option value="">Todos os status</option><?php foreach(ReservationStatus::cases() as $s): ?><option value="<?= e($s->value) ?>" <?= ($filters['status']??'')===$s->value?'selected':'' ?>><?= e($s->label()) ?></option><?php endforeach; ?></select><select name="origem"><option value="">Todas as origens</option><?php foreach(['SITE_DIRETO','AIRBNB','BOOKING','MANUAL'] as $o): ?><option <?= ($filters['origem']??'')===$o?'selected':'' ?>><?= e($o) ?></option><?php endforeach; ?></select><input type="date" name="inicio" value="<?= e($filters['inicio']??'') ?>"><input type="date" name="fim" value="<?= e($filters['fim']??'') ?>"><select name="ordem"><option value="created_at">Mais recentes</option><option value="checkin" <?= ($filters['ordem']??'')==='checkin'?'selected':'' ?>>Check-in</option><option value="nome_cliente" <?= ($filters['ordem']??'')==='nome_cliente'?'selected':'' ?>>Nome</option></select><button class="admin-primary" type="submit">Filtrar</button></form><section class="admin-panel"><div class="table-wrap"><table><thead><tr><th>Codigo</th><th>Cliente</th><th>Contato</th><th>Datas</th><th>Origem</th><th>Status</th></tr></thead><tbody><?php foreach($result['items'] as $r): ?><tr data-href="<?= e(base_url('admin/reservas/'.$r['id'])) ?>"><td><a href="<?= e(base_url('admin/reservas/'.$r['id'])) ?>"><?= e($r['codigo']) ?></a></td><td><?= e($r['nome_cliente']) ?></td><td><?= e($r['telefone']) ?><br><small><?= e($r['email']) ?></small></td><td><?= date('d/m/Y',strtotime($r['checkin'])) ?><br><?= date('d/m/Y',strtotime($r['checkout'])) ?></td><td><?= e($r['origem']) ?></td><td><span class="admin-status status-<?= strtolower($r['status']) ?>"><?= e(ReservationStatus::from($r['status'])->label()) ?></span></td></tr><?php endforeach; ?><?php if(!$result['items']): ?><tr><td colspan="6">Nenhuma reserva encontrada.</td></tr><?php endif; ?></tbody></table></div></section><?php $pages=(int)ceil($result['total']/$result['per_page']); if($pages>1): ?><nav class="pagination"><?php for($i=1;$i<=$pages;$i++): ?><a class="<?= $i===$page?'active':'' ?>" href="?<?= e(http_build_query(array_merge($filters,['pagina'=>$i]))) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?><?php require __DIR__.'/_bottom.php'; ?>
